1	import http from "node:http";
2	import path from "node:path";
3	import { readdir } from "node:fs/promises";
4	import { createServer as createViteServer } from "vite";
5	import { readRuns, replayLines } from "./replay.ts";
6	
7	const PORT = Number(process.env.PORT ?? 8787);
8	const HOST = "127.0.0.1";
9	const FIXTURES_DIR = path.resolve("fixtures");
10	const DEFAULT_FIXTURE = "trace.jsonl";
11	const REPLAY_DELAY_MS = Number(process.env.REPLAY_DELAY_MS ?? 120);
12	
13	const vite = await createViteServer({ server: { middlewareMode: true }, appType: "spa" });
14	
15	async function listFixtures(res: http.ServerResponse) {
16	  const names = (await readdir(FIXTURES_DIR)).filter((name) => name.endsWith(".jsonl")).sort();
17	  const fixtures = await Promise.all(names.map(async (name) => ({ name, runs: (await readRuns(path.join(FIXTURES_DIR, name))).length })));
18	  res.writeHead(200, { "Content-Type": "application/json" });
19	  res.end(JSON.stringify(fixtures));
20	}
21	
22	// Replays one run of a fixture (?run=N, 1-based), so each request stands in for one follow-up prompt.
23	async function handleReplay(url: URL, res: http.ServerResponse) {
24	  // Only bare .jsonl names inside fixtures/ are accepted, so the query cannot reach other files.
25	  const name = url.searchParams.get("file") ?? DEFAULT_FIXTURE;
26	  if (path.basename(name) !== name || !name.endsWith(".jsonl")) {
27	    res.writeHead(400).end(`invalid fixture name: ${name}`);
28	    return;
29	  }
30	  let runs: string[][];
31	  try {
32	    runs = await readRuns(path.join(FIXTURES_DIR, name));
33	  } catch {
34	    res.writeHead(404).end(`no such fixture: ${name}`);
35	    return;
36	  }
37	  const run = Number(url.searchParams.get("run") ?? 1);
38	  if (!Number.isInteger(run) || run < 1 || run > runs.length) {
39	    res.writeHead(400).end(`${name} has ${runs.length} run(s); run=${url.searchParams.get("run")} is out of range`);
40	    return;
41	  }
42	
43	  const abort = new AbortController();
44	  res.on("close", () => abort.abort());
45	  res.writeHead(200, {
46	    "Content-Type": "application/x-ndjson; charset=utf-8",
47	    "Cache-Control": "no-cache",
48	    "X-Content-Type-Options": "nosniff",
49	  });
50	  try {
51	    for await (const line of replayLines(runs[run - 1], REPLAY_DELAY_MS, abort.signal)) {
52	      res.write(line + "\n");
53	    }
54	  } catch (err) {
55	    console.error("replay failed:", err);
56	  }
57	  res.end();
58	}
59	
60	const server = http.createServer((req, res) => {
61	  const url = new URL(req.url ?? "/", `http://${req.headers.host}`);
62	  if (req.method === "GET" && url.pathname === "/api/fixtures") {
63	    void listFixtures(res);
64	    return;
65	  }
66	  if (req.method === "GET" && url.pathname === "/api/replay") {
67	    void handleReplay(url, res);
68	    return;
69	  }
70	  vite.middlewares(req, res);
71	});
72	
73	server.listen(PORT, HOST, () => {
74	  console.log(`Trajectory viewer: http://${HOST}:${PORT}`);
75	  console.log(`Replaying fixtures from ${FIXTURES_DIR} (${REPLAY_DELAY_MS} ms/line)`);
76	});
