1	import { useEffect, useRef, useState, type ReactNode } from "react";
2	import type { ToolItem } from "../trajectory.ts";
3	import { ToolResultView } from "./ToolResult.tsx";
4	
5	const CATEGORIES: Record<string, string> = {
6	  Read: "read",
7	  Grep: "read",
8	  Glob: "read",
9	  LS: "read",
10	  Edit: "write",
11	  MultiEdit: "write",
12	  Write: "write",
13	  NotebookEdit: "write",
14	  Bash: "exec",
15	  BashOutput: "exec",
16	  KillShell: "exec",
17	  Agent: "agent",
18	  Task: "agent",
19	};
20	
21	export function toolCategory(name: string): string {
22	  return CATEGORIES[name] ?? "other";
23	}
24	
25	interface ToolCallProps {
26	  item: ToolItem;
27	  cwd: string;
28	  runEnded: boolean;
29	  // Set when the outline asked to jump to this call; the call scrolls itself into view and reports back.
30	  focused?: boolean;
31	  onFocused?: () => void;
32	  children?: ReactNode;
33	}
34	
35	// children (a subagent's nested events) render between the call and its result,
36	// since the result of an Agent call is the report the subagent hands back.
37	export function ToolCall({ item, cwd, runEnded, focused, onFocused, children }: ToolCallProps) {
38	  const [open, setOpen] = useState(false);
39	  const ref = useRef<HTMLDivElement>(null);
40	  const failed = item.result?.isError === true;
41	
42	  // Runs on mount too, so a call revealed by expanding a folded subagent group still gets scrolled to.
43	  useEffect(() => {
44	    const el = ref.current;
45	    if (!focused || !el) return;
46	    el.scrollIntoView({ block: "center", behavior: "smooth" });
47	    el.classList.remove("flash");
48	    void el.offsetWidth; // restart the highlight animation when the same call is picked again
49	    el.classList.add("flash");
50	    onFocused?.();
51	  }, [focused, onFocused]);
52	
53	  return (
54	    <div ref={ref} id={`call-${item.id}`} className={failed ? "item tool tool-failed" : "item tool"}>
55	      <button className="tool-row" onClick={() => setOpen((o) => !o)} aria-expanded={open}>
56	        <span className={`badge badge-${toolCategory(item.name)}`}>{item.name}</span>
57	        <span className="tool-summary">{summarize(item, cwd)}</span>
58	        <CallStatus item={item} runEnded={runEnded} />
59	        <span className="chevron" aria-hidden>
60	          {open ? "▾" : "▸"}
61	        </span>
62	      </button>
63	      {open && <pre className="tool-input">{JSON.stringify(item.input, null, 2)}</pre>}
64	      {children}
65	      {item.result && <ToolResultView result={item.result} />}
66	    </div>
67	  );
68	}
69	
70	// Pending from the moment the tool_use arrives until its tool_result attaches.
71	// A call still without a result after its run ended will never get one, so it stops showing as pending.
72	function CallStatus({ item, runEnded }: { item: ToolItem; runEnded: boolean }) {
73	  if (item.result) {
74	    return item.result.isError ? <span className="fail-mark">failed</span> : <span className="call-ok" aria-label="succeeded">✓</span>;
75	  }
76	  if (runEnded) return <span className="call-none">no result</span>;
77	  return (
78	    <span className="call-pending">
79	      <span className="spinner" aria-hidden /> pending
80	    </span>
81	  );
82	}
83	
84	// One line that says what the call is about, so the full input JSON can stay folded.
85	export function summarize({ name, input }: ToolItem, cwd: string): string {
86	  const str = (key: string) => (typeof input[key] === "string" ? (input[key] as string) : "");
87	  switch (name) {
88	    case "Bash":
89	      return firstLine(str("command"));
90	    case "Read":
91	    case "Write":
92	    case "Edit":
93	    case "MultiEdit":
94	    case "NotebookEdit":
95	      return relativize(str("file_path") || str("notebook_path"), cwd);
96	    case "Grep":
97	    case "Glob":
98	      return str("pattern");
99	    case "Agent":
100	    case "Task":
101	      return str("description");
102	    case "WebFetch":
103	      return str("url");
104	    case "WebSearch":
105	    case "ToolSearch":
106	      return str("query");
107	    case "TaskCreate":
108	      return str("subject");
109	  }
110	  return JSON.stringify(input).slice(0, 160);
111	}
112	
113	function firstLine(text: string): string {
114	  const [first, ...rest] = text.split("\n");
115	  return rest.length > 0 ? `${first} …` : first;
116	}
117	
118	// macOS reports the same temp dir as both /var/... and /private/var/..., so try both spellings of cwd.
119	function relativize(file: string, cwd: string): string {
120	  if (!cwd) return file;
121	  const prefixes = [cwd, cwd.replace(/^\/private/, ""), `/private${cwd}`];
122	  for (const prefix of prefixes) {
123	    if (file.startsWith(prefix + "/")) return file.slice(prefix.length + 1);
124	  }
125	  return file;
126	}
