1	import { useEffect, useState } from "react";
2	import { groupByParent, type ChildMap, type Item, type ToolItem } from "../trajectory.ts";
3	import { TextBlock } from "./TextBlock.tsx";
4	import { ToolCall } from "./ToolCall.tsx";
5	
6	interface Context {
7	  cwd: string;
8	  runEnded: boolean;
9	  children: ChildMap;
10	  // The call the outline asked to jump to, until that call has scrolled itself into view.
11	  focus: string | null;
12	  onFocused: () => void;
13	}
14	
15	interface ItemListProps {
16	  items: Item[];
17	  cwd: string;
18	  runEnded: boolean;
19	  focus: string | null;
20	  onFocused: () => void;
21	}
22	
23	// Renders a run's items as a tree: events a subagent emitted nest under the Agent/Task call that spawned it.
24	// A run without subagents has only top-level items, so it renders as a flat list.
25	export function ItemList({ items, cwd, runEnded, focus, onFocused }: ItemListProps) {
26	  const ctx: Context = { cwd, runEnded, children: groupByParent(items), focus, onFocused };
27	  return <Items list={ctx.children.get(null) ?? []} ctx={ctx} />;
28	}
29	
30	function Items({ list, ctx }: { list: Item[]; ctx: Context }) {
31	  return (
32	    <>
33	      {list.map((item) =>
34	        item.kind === "text" ? (
35	          <TextBlock key={item.key} text={item.text} />
36	        ) : (
37	          <ToolCall
38	            key={item.key}
39	            item={item}
40	            cwd={ctx.cwd}
41	            runEnded={ctx.runEnded}
42	            focused={ctx.focus === item.id}
43	            onFocused={ctx.onFocused}
44	          >
45	            {(item.subagent || ctx.children.has(item.id)) && <SubagentGroup call={item} ctx={ctx} />}
46	          </ToolCall>
47	        ),
48	      )}
49	    </>
50	  );
51	}
52	
53	// Open while the subagent works, folded once it is done, unless the reader has toggled it.
54	function SubagentGroup({ call, ctx }: { call: ToolItem; ctx: Context }) {
55	  const [userOpen, setUserOpen] = useState<boolean | null>(null);
56	  const done = isDone(call, ctx.runEnded);
57	  const open = userOpen ?? !done;
58	  const count = countEvents(call.id, ctx.children);
59	  const events = count === 1 ? "1 event" : `${count} events`;
60	  const status = call.subagent?.status;
61	
62	  // A jump from the outline to a call inside this group unfolds it, so the call can be shown.
63	  useEffect(() => {
64	    if (ctx.focus && containsCall(call.id, ctx.focus, ctx.children)) setUserOpen(true);
65	  }, [ctx.focus]); // eslint-disable-line react-hooks/exhaustive-deps
66	
67	  return (
68	    <div className="subagent">
69	      <button className="subagent-head" onClick={() => setUserOpen(!open)} aria-expanded={open}>
70	        <span className="subagent-chevron">{open ? "▾" : "▸"}</span>
71	        <span>subagent</span>
72	        {call.subagent?.type && <span className="subagent-meta">· {call.subagent.type}</span>}
73	        {call.subagent?.background && <span className="subagent-meta">· background</span>}
74	        {done && status && status !== "completed" && <span className="subagent-meta">· {status}</span>}
75	        <span className="subagent-meta">· {open ? events : `${events} collapsed`}</span>
76	        {!done && (
77	          <span className="call-pending">
78	            <span className="spinner" aria-hidden /> running
79	          </span>
80	        )}
81	      </button>
82	      {open && (
83	        <div className="subagent-body">
84	          <Items list={ctx.children.get(call.id) ?? []} ctx={ctx} />
85	        </div>
86	      )}
87	    </div>
88	  );
89	}
90	
91	// The harness's task status is authoritative when present: a background subagent's tool_result
92	// arrives at launch, long before it finishes. Without it, the call's result marks the end.
93	function isDone(call: ToolItem, runEnded: boolean): boolean {
94	  if (runEnded) return true;
95	  return call.subagent ? call.subagent.status !== "running" : call.result !== undefined;
96	}
97	
98	function countEvents(id: string, children: ChildMap): number {
99	  return (children.get(id) ?? []).reduce((n, item) => n + 1 + (item.kind === "tool" ? countEvents(item.id, children) : 0), 0);
100	}
101	
102	function containsCall(rootId: string, targetId: string, children: ChildMap): boolean {
103	  return (children.get(rootId) ?? []).some(
104	    (item) => item.kind === "tool" && (item.id === targetId || containsCall(item.id, targetId, children)),
105	  );
106	}
