1	import { useLayoutEffect, useRef } from "react";
2	import { groupByParent, type ChildMap, type Item, type Run, type ToolItem } from "../trajectory.ts";
3	import { summarize, toolCategory } from "./ToolCall.tsx";
4	
5	const RUN_MARK = { running: "●", finished: "✓", failed: "✕" } as const;
6	
7	// A table of contents for the whole trajectory: just the call names, nested the same way as the dialogue.
8	// Clicking a name asks the dialogue to jump to that call.
9	export function Outline({ runs, onJump }: { runs: Run[]; onJump: (id: string) => void }) {
10	  const ref = useRef<HTMLElement>(null);
11	  const atBottom = useRef(true);
12	
13	  // Keep following new calls while the outline is scrolled to its end.
14	  useLayoutEffect(() => {
15	    const el = ref.current;
16	    if (el && atBottom.current) el.scrollTop = el.scrollHeight;
17	  }, [runs]);
18	
19	  return (
20	    <nav
21	      ref={ref}
22	      className="outline"
23	      aria-label="Trajectory outline"
24	      onScroll={(e) => {
25	        const el = e.currentTarget;
26	        atBottom.current = el.scrollTop + el.clientHeight >= el.scrollHeight - 24;
27	      }}
28	    >
29	      <div className="outline-title">Outline</div>
30	      {runs.length === 0 && <p className="outline-empty">Calls appear here as a run streams in.</p>}
31	      {runs.map((run) => {
32	        const tree = groupByParent(run.items);
33	        const calls = onlyCalls(tree.get(null));
34	        return (
35	          <section key={run.index} className="outline-run">
36	            <div className="outline-run-head">
37	              Run {run.index}
38	              <span className={`outline-run-${run.status}`}>{RUN_MARK[run.status]}</span>
39	            </div>
40	            {calls.length > 0 ? (
41	              <OutlineCalls calls={calls} run={run} tree={tree} onJump={onJump} />
42	            ) : (
43	              <div className="outline-empty">no tool calls</div>
44	            )}
45	          </section>
46	        );
47	      })}
48	    </nav>
49	  );
50	}
51	
52	interface OutlineCallsProps {
53	  calls: ToolItem[];
54	  run: Run;
55	  tree: ChildMap;
56	  onJump: (id: string) => void;
57	}
58	
59	function OutlineCalls({ calls, run, tree, onJump }: OutlineCallsProps) {
60	  const runEnded = run.status !== "running";
61	  return (
62	    <ul className="outline-list">
63	      {calls.map((call) => {
64	        const nested = onlyCalls(tree.get(call.id));
65	        const state = call.result?.isError ? " outline-chip-failed" : !call.result && !runEnded ? " outline-chip-pending" : "";
66	        return (
67	          <li key={call.key}>
68	            <button
69	              className={`outline-chip badge-${toolCategory(call.name)}${state}`}
70	              title={summarize(call, run.cwd)}
71	              onClick={() => onJump(call.id)}
72	            >
73	              {call.name}
74	            </button>
75	            {nested.length > 0 && <OutlineCalls calls={nested} run={run} tree={tree} onJump={onJump} />}
76	          </li>
77	        );
78	      })}
79	    </ul>
80	  );
81	}
82	
83	function onlyCalls(items: Item[] | undefined): ToolItem[] {
84	  return (items ?? []).filter((item): item is ToolItem => item.kind === "tool");
85	}
