1	import { useState } from "react";
2	import type { ToolResult } from "../trajectory.ts";
3	
4	// A folded result shows this many lines, and clips any single line longer than the char limit.
5	const FOLDED_LINES = 8;
6	const FOLDED_LINE_CHARS = 300;
7	
8	export function ToolResultView({ result }: { result: ToolResult }) {
9	  const [expanded, setExpanded] = useState(false);
10	  const text = result.text.replace(/\n+$/, "");
11	  if (!text.trim()) return <div className="tool-result tool-result-empty">(no output)</div>;
12	
13	  const lines = text.split("\n");
14	  const hiddenLines = lines.length - FOLDED_LINES;
15	  const hasLongLine = lines.some((line) => line.length > FOLDED_LINE_CHARS);
16	  const foldable = hiddenLines > 0 || hasLongLine;
17	  const shown = expanded || !foldable ? text : lines.slice(0, FOLDED_LINES).map(clip).join("\n");
18	
19	  return (
20	    <div className="tool-result">
21	      <pre className={expanded ? "expanded" : undefined}>{shown}</pre>
22	      {foldable && (
23	        <button className="fold-toggle" onClick={() => setExpanded((e) => !e)} aria-expanded={expanded}>
24	          {expanded ? "▾ fold" : hiddenLines > 0 ? `▸ ${hiddenLines} more ${hiddenLines === 1 ? "line" : "lines"}, folded` : "▸ show full lines"}
25	        </button>
26	      )}
27	    </div>
28	  );
29	}
30	
31	function clip(line: string): string {
32	  return line.length > FOLDED_LINE_CHARS ? `${line.slice(0, FOLDED_LINE_CHARS)}…` : line;
33	}
