1	import { useCallback, useEffect, useLayoutEffect, useReducer, useRef, useState } from "react";
2	import { ItemList } from "./components/ItemList.tsx";
3	import { Outline } from "./components/Outline.tsx";
4	import { readNdjson } from "./ndjson.ts";
5	import { emptyTrajectory, reducer, type Run, type RunStats, type RunStatus } from "./trajectory.ts";
6	
7	type Status =
8	  | { kind: "idle" }
9	  | { kind: "streaming"; run: number }
10	  | { kind: "done"; run: number }
11	  | { kind: "error"; run: number; message: string };
12	
13	interface Fixture {
14	  name: string;
15	  runs: number;
16	}
17	
18	export function App() {
19	  const [trajectory, dispatch] = useReducer(reducer, emptyTrajectory);
20	  const [status, setStatus] = useState<Status>({ kind: "idle" });
21	  const [fixtures, setFixtures] = useState<Fixture[]>([]);
22	  const [fixture, setFixture] = useState("trace.jsonl");
23	  // The run the button plays next (1-based). Back at 1 once every run of the fixture has been played.
24	  const [nextRun, setNextRun] = useState(1);
25	  const totalRuns = fixtures.find((f) => f.name === fixture)?.runs ?? 1;
26	  // The call an outline click asked to show; cleared once that call has scrolled itself into view.
27	  const [focus, setFocus] = useState<string | null>(null);
28	  const [outlineOpen, setOutlineOpen] = useState(false);
29	  const clearFocus = useCallback(() => setFocus(null), []);
30	  const nearBottom = useNearBottom();
31	
32	  function jump(id: string) {
33	    setFocus(id);
34	    setOutlineOpen(false);
35	  }
36	
37	  useEffect(() => {
38	    fetch("/api/fixtures")
39	      .then((res) => res.json())
40	      .then(setFixtures)
41	      .catch(() => setFixtures([]));
42	  }, []);
43	
44	  // Follow new events only while the reader is already at the bottom, so scrolling up to read is not interrupted.
45	  useLayoutEffect(() => {
46	    if (nearBottom.current) window.scrollTo({ top: document.documentElement.scrollHeight });
47	  }, [trajectory, nearBottom]);
48	
49	  function chooseFixture(name: string) {
50	    setFixture(name);
51	    setNextRun(1);
52	    setStatus({ kind: "idle" });
53	    dispatch({ type: "reset" });
54	  }
55	
56	  // Plays one run per click. Run 1 starts a fresh trajectory; later runs are appended below it,
57	  // the way a follow-up prompt continues the same session.
58	  async function replay() {
59	    const run = nextRun;
60	    if (run === 1) dispatch({ type: "reset" });
61	    setStatus({ kind: "streaming", run });
62	    try {
63	      const res = await fetch(`/api/replay?file=${encodeURIComponent(fixture)}&run=${run}`);
64	      if (!res.ok || !res.body) throw new Error(`replay request failed (HTTP ${res.status})`);
65	      for await (const event of readNdjson(res.body)) dispatch({ type: "event", event });
66	      dispatch({ type: "end" });
67	      setStatus({ kind: "done", run });
68	    } catch (err) {
69	      const message = err instanceof Error ? err.message : String(err);
70	      dispatch({ type: "end", error: message });
71	      setStatus({ kind: "error", run, message });
72	    }
