40	// Groups a run's items under the Agent/Task call that spawned them (parent_tool_use_id), turning the flat
41	// event list into a tree. A run without subagents ends up with only top-level items.
42	export function groupByParent(items: Item[]): ChildMap {
43	  const toolIds = new Set(items.flatMap((item) => (item.kind === "tool" ? [item.id] : [])));
44	  const groups: ChildMap = new Map();
45	  for (const item of items) {
46	    // An event whose spawning call is not in this run stays visible at the top level instead of being dropped.
47	    const parent = item.parentId && toolIds.has(item.parentId) ? item.parentId : null;
48	    const group = groups.get(parent);
49	    if (group) group.push(item);
50	    else groups.set(parent, [item]);
51	  }
52	  return groups;
53	}
