80	export interface Trajectory {
81	  runs: Run[];
82	  eventCount: number;
83	}
84	
85	export const emptyTrajectory: Trajectory = { runs: [], eventCount: 0 };
86	
87	// "end" is dispatched when the event stream closes, with an error if the request itself failed.
88	export type Action = { type: "reset" } | { type: "event"; event: StreamEvent } | { type: "end"; error?: string };
89	
90	export function reducer(state: Trajectory, action: Action): Trajectory {
91	  if (action.type === "reset") return emptyTrajectory;
92	  if (action.type === "end") return endStream(state, action.error);
93	  return applyEvent(state, action.event);
94	}
