100	// A run that is still running when the stream closes never got its result event, so it failed.
101	// If nothing arrived at all, a placeholder run carries the failure so it is still visible.
102	function endStream(state: Trajectory, error?: string): Trajectory {
103	  const failure = error
104	    ? { kind: "request failed", message: error }
105	    : { kind: "stream ended", message: "The event stream ended before the run's result event arrived." };
106	  if (state.runs.length === 0) return { ...state, runs: [newRun(1, { status: "failed", failure })] };
107	  const runs = state.runs.map((run) => (run.status === "running" ? { ...run, status: "failed" as const, failure } : run));
108	  return { ...state, runs };
109	}
