111	function applyEvent(state: Trajectory, ev: StreamEvent): Trajectory {
112	  const eventCount = state.eventCount + 1;
113	
114	  // Each init event starts a new run (a resumed session prints a fresh init).
115	  if (isInit(ev)) {
116	    const resumed = state.runs.some((r) => r.sessionId === ev.session_id);
117	    const run = newRun(state.runs.length + 1, { sessionId: ev.session_id, model: ev.model, cwd: ev.cwd, resumed });
118	    return { runs: [...state.runs, run], eventCount };
119	  }
120	
121	  // The result event closes the current run: is_error decides finished vs failed.
122	  if (isResult(ev) && state.runs.length > 0) {
123	    const current = state.runs[state.runs.length - 1];
124	    const stats: RunStats = {
125	      runCostUsd: runCost(state.runs.slice(0, -1), current, ev.total_cost_usd),
126	      sessionCostUsd: ev.total_cost_usd,
127	      durationMs: ev.duration_ms,
128	      numTurns: ev.num_turns,
129	    };
130	    const last = { ...current, origin: ev.origin?.kind, stats };
131	    const ended: Run = ev.is_error
132	      ? { ...last, status: "failed", failure: { kind: ev.subtype, message: ev.errors?.join("\n") || ev.subtype } }
133	      : { ...last, status: "finished" };
134	    return { runs: [...state.runs.slice(0, -1), ended], eventCount };
135	  }
136	
137	  // Assistant events carry one content block each; text and tool_use become items, thinking is skipped.
138	  // Partial-message stream_events are ignored because the complete assistant event always follows them.
139	  if (isAssistant(ev)) {
140	    const runs = state.runs.length > 0 ? state.runs : [newRun(1)];
141	    const last = runs[runs.length - 1];
142	    const items = [...last.items];
143	    const parentId = ev.parent_tool_use_id ?? null;
144	    for (const block of ev.message.content) {
145	      const key = `${last.index}:${items.length}`;
146	      if (block.type === "text" && block.text.trim()) {
147	        items.push({ kind: "text", key, text: block.text, parentId });
148	      } else if (block.type === "tool_use") {
149	        items.push({ kind: "tool", key, id: block.id, name: block.name, input: block.input ?? {}, parentId });
150	      }
151	    }
152	    return { runs: [...runs.slice(0, -1), { ...last, items }], eventCount };
153	  }
154	
155	  // Tool results come back in user events; attach each one to the call with the same tool_use_id.
156	  if (isUser(ev) && Array.isArray(ev.message.content)) {
157	    let runs = state.runs;
158	    for (const block of ev.message.content) {
159	      if (block.type === "tool_result") runs = attachResult(runs, block as ToolResultContent);
160	    }
161	    return { runs, eventCount };
162	  }
163	
164	  if (isTask(ev)) return { runs: updateSubagent(state.runs, ev), eventCount };
165	
166	  return { ...state, eventCount };
167	}
