169	// task_started announces the subagent behind an Agent/Task call; task_updated and task_notification report
170	// when it ends. For a background subagent this is the only signal, since its tool_result returns at launch.
171	function updateSubagent(runs: Run[], ev: TaskEvent): Run[] {
172	  if (ev.subtype === "task_started") {
173	    const subagent: Subagent = { taskId: ev.task_id, type: ev.subagent_type, background: ev.is_backgrounded === true, status: "running" };
174	    return updateTool(runs, (t) => t.id === ev.tool_use_id, (t) => ({ ...t, subagent }));
175	  }
176	  const status = ev.subtype === "task_updated" ? ev.patch?.status : ev.status;
177	  if (!status) return runs;
178	  const matches = (t: ToolItem) => (ev.tool_use_id ? t.id === ev.tool_use_id : t.subagent?.taskId === ev.task_id);
179	  return updateTool(runs, matches, (t) => ({ ...t, subagent: { ...(t.subagent ?? { taskId: ev.task_id, background: false }), status } }));
180	}
