182	// total_cost_usd keeps counting across a session, so this run's share is the difference from the
183	// previous run of the same session. The first run of a session starts from zero.
184	function runCost(earlier: Run[], run: Run, sessionTotal: number): number | undefined {
185	  const previous = earlier.findLast((r) => r.sessionId === run.sessionId && r.stats);
186	  if (previous?.stats) return sessionTotal - previous.stats.sessionCostUsd;
187	  return run.resumed ? undefined : sessionTotal;
188	}
