190	function attachResult(runs: Run[], block: ToolResultContent): Run[] {
191	  const result: ToolResult = { text: resultText(block.content), isError: block.is_error === true };
192	  return updateTool(runs, (t) => t.id === block.tool_use_id, (t) => ({ ...t, result }));
193	}
194	
195	// Replaces the first tool call matching pred. Searches the newest run first, since a result or
196	// lifecycle event almost always belongs to a call from the current run.
197	function updateTool(runs: Run[], pred: (t: ToolItem) => boolean, update: (t: ToolItem) => ToolItem): Run[] {
198	  for (let r = runs.length - 1; r >= 0; r--) {
199	    const i = runs[r].items.findIndex((item) => item.kind === "tool" && pred(item));
200	    if (i === -1) continue;
201	    const items = [...runs[r].items];
202	    items[i] = update(items[i] as ToolItem);
203	    return runs.map((run, k) => (k === r ? { ...run, items } : run));
204	  }
205	  return runs;
206	}
