212	    .map((part) => {
213	      if (part.type === "text") return part.text ?? "";
214	      if (part.type === "tool_reference") return `loaded tool: ${part.tool_name}`;
215	      if (part.type === "image") return "[image]";
216	      return `[${part.type}]`;
217	    })
218	    .join("\n");
